PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?activity ?activityLabel ?flow ?flowLabel ?flowType
WHERE {
  ?activity a oriont:Activity .
  ?activity rdfs:label ?activityLabel .

  OPTIONAL {
    { ?inputFlow oriont:isInputOf ?activity . BIND(?inputFlow AS ?flow) . BIND("Input" AS ?flowType) }
    UNION
    { ?outputFlow oriont:isOutputOf ?activity . BIND(?outputFlow AS ?flow) . BIND("Output" AS ?flowType) }
    ?flow rdfs:label ?flowLabel .
  }
}

